dead() { local s t=$((SECONDS+${2:-30})); while ((SECONDS < t)); do read -r s 2>/dev/null < /proc/$1/stat || return 0; [[ $s == *") Z "* ]] && return 0; done; return 1; }; alive() { local s; read -r s 2>/dev/null < /proc/$1/stat && [[ $s != *") Z "* ]]; }
d=$(mktemp -d); cd "$d"; /bin/sh -c 'echo $$ >parent; (until test -e release; do /bin/sleep .01; done; echo CHILD >>log) & echo $! >hCHILD; exit 0' | cat & p=$!; until [ -s parent ] && [ -s hCHILD ]; do :; done; read first <parent; read h <hCHILD; dead $first
echo NEXT; kill -0 $first 2>/dev/null; echo k0=$?; touch release; dead $h; wait "$p"; echo wait=$?; cat log; cd /; rm -rf "$d"

